using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Square.Core.Models;

namespace Square.Models;

/// <summary>
/// Describes a request to create a payment using
/// <see href="api-endpoint:Payments-CreatePayment">CreatePayment</see>.
/// </summary>
public record CreatePaymentRequest
{
    /// <summary>
    /// The ID for the source of funds for this payment.
    /// This could be a payment token generated by the Web Payments SDK for any of its
    /// <see href="https://developer.squareup.com/docs/web-payments/overview#explore-payment-methods">supported methods</see>,
    /// including cards, bank transfers, Afterpay or Cash App Pay. If recording a payment
    /// that the seller received outside of Square, specify either "CASH" or "EXTERNAL".
    /// For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments">Take Payments</see>.
    /// </summary>
    [JsonPropertyName("source_id")]
    [MinLength(1)]
    public required string SourceId { get; init; }

    /// <summary>
    /// A unique string that identifies this <c>CreatePayment</c> request. Keys can be any valid string
    /// but must be unique for every <c>CreatePayment</c> request.
    /// <para>
    /// Note: The number of allowed characters might be less than the stated maximum, if multi-byte
    /// characters are used.
    /// </para>
    /// <para>
    /// For more information, see <see href="https://developer.squareup.com/docs/working-with-apis/idempotency">Idempotency</see>.
    /// </para>
    /// </summary>
    [JsonPropertyName("idempotency_key")]
    [StringLength(45, MinimumLength = 1)]
    public required string IdempotencyKey { get; init; }

    /// <summary>
    /// Represents an amount of money. <c>Money</c> fields can be signed or unsigned.
    /// Fields that do not explicitly define whether they are signed or unsigned are
    /// considered unsigned and can only hold positive amounts. For signed fields, the
    /// sign of the value indicates the purpose of the money transfer. See
    /// <see href="https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts">Working with Monetary Amounts</see>
    /// for more information.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("amount_money")]
    public Money? AmountMoney { get; init; }

    /// <summary>
    /// Represents an amount of money. <c>Money</c> fields can be signed or unsigned.
    /// Fields that do not explicitly define whether they are signed or unsigned are
    /// considered unsigned and can only hold positive amounts. For signed fields, the
    /// sign of the value indicates the purpose of the money transfer. See
    /// <see href="https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts">Working with Monetary Amounts</see>
    /// for more information.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("tip_money")]
    public Money? TipMoney { get; init; }

    /// <summary>
    /// Represents an amount of money. <c>Money</c> fields can be signed or unsigned.
    /// Fields that do not explicitly define whether they are signed or unsigned are
    /// considered unsigned and can only hold positive amounts. For signed fields, the
    /// sign of the value indicates the purpose of the money transfer. See
    /// <see href="https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts">Working with Monetary Amounts</see>
    /// for more information.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("app_fee_money")]
    public Money? AppFeeMoney { get; init; }

    /// <summary>
    /// The duration of time after the payment's creation when Square automatically
    /// either completes or cancels the payment depending on the <c>delay_action</c> field value.
    /// For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments/card-payments/delayed-capture#time-threshold">Time threshold</see>.
    /// <para>
    /// This parameter should be specified as a time duration, in RFC 3339 format.
    /// </para>
    /// <para>
    /// Note: This feature is only supported for card payments. This parameter can only be set for a delayed
    /// capture payment (<c>autocomplete=false</c>).
    /// </para>
    /// <para>
    /// Default:
    /// </para>
    /// <list type="bullet">
    ///   <item><description>Card-present payments: "PT36H" (36 hours) from the creation time.</description></item>
    ///   <item><description>Card-not-present payments: "P7D" (7 days) from the creation time.</description></item>
    /// </list>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("delay_duration")]
    public string? DelayDuration { get; init; }

    /// <summary>
    /// The action to be applied to the payment when the <c>delay_duration</c> has elapsed. The action must be
    /// CANCEL or COMPLETE. For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments/card-payments/delayed-capture#time-threshold">Time Threshold</see>.
    /// <para>
    /// Default: CANCEL
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("delay_action")]
    public string? DelayAction { get; init; }

    /// <summary>
    /// If set to <c>true</c>, this payment will be completed when possible. If
    /// set to <c>false</c>, this payment is held in an approved state until either
    /// explicitly completed (captured) or canceled (voided). For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments/card-payments#delayed-capture-of-a-card-payment">Delayed capture</see>.
    /// <para>
    /// Default: true
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("autocomplete")]
    public bool? Autocomplete { get; init; }

    /// <summary>
    /// Associates a previously created order with this payment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("order_id")]
    public string? OrderId { get; init; }

    /// <summary>
    /// The <see href="entity:Customer">Customer</see> ID of the customer associated with the payment.
    /// <para>
    /// This is required if the <c>source_id</c> refers to a card on file created using the Cards API.
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("customer_id")]
    public string? CustomerId { get; init; }

    /// <summary>
    /// The location ID to associate with the payment. If not specified, the <see href="https://developer.squareup.com/docs/locations-api#about-the-main-location">main location</see> is
    /// used.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("location_id")]
    public string? LocationId { get; init; }

    /// <summary>
    /// An optional <see href="entity:TeamMember">TeamMember</see> ID to associate with
    /// this payment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("team_member_id")]
    public string? TeamMemberId { get; init; }

    /// <summary>
    /// A user-defined ID to associate with the payment.
    /// <para>
    /// You can use this field to associate the payment to an entity in an external system
    /// (for example, you might specify an order ID that is generated by a third-party shopping cart).
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("reference_id")]
    [MaxLength(40)]
    public string? ReferenceId { get; init; }

    /// <summary>
    /// An identifying token generated by <see href="https://developer.squareup.com/reference/sdks/web/payments/objects/Payments#Payments.verifyBuyer">payments.verifyBuyer()</see>.
    /// Verification tokens encapsulate customer device information and 3-D Secure
    /// challenge results to indicate that Square has verified the buyer identity.
    /// <para>
    /// For more information, see <see href="https://developer.squareup.com/docs/sca-overview">SCA Overview</see>.
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("verification_token")]
    public string? VerificationToken { get; init; }

    /// <summary>
    /// If set to <c>true</c> and charging a Square Gift Card, a payment might be returned with
    /// <c>amount_money</c> equal to less than what was requested. For example, a request for $20 when charging
    /// a Square Gift Card with a balance of $5 results in an APPROVED payment of $5. You might choose
    /// to prompt the buyer for an additional payment to cover the remainder or cancel the Gift Card
    /// payment. This field cannot be <c>true</c> when <c>autocomplete = true</c>.
    /// <para>
    /// For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments#partial-payment-gift-card">Partial amount with Square Gift Cards</see>.
    /// </para>
    /// <para>
    /// Default: false
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("accept_partial_authorization")]
    public bool? AcceptPartialAuthorization { get; init; }

    /// <summary>
    /// The buyer's email address.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("buyer_email_address")]
    [MaxLength(255)]
    public string? BuyerEmailAddress { get; init; }

    /// <summary>
    /// The buyer's phone number.
    /// Must follow the following format:
    /// 1. A leading + symbol (followed by a country code)
    /// 2. The phone number can contain spaces and the special characters <c>(</c> , <c>)</c> , <c>-</c> , and <c>.</c>.
    /// Alphabetical characters aren't allowed.
    /// 3. The phone number must contain between 9 and 16 digits.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("buyer_phone_number")]
    public string? BuyerPhoneNumber { get; init; }

    /// <summary>
    /// Represents a postal address in a country.
    /// For more information, see <see href="https://developer.squareup.com/docs/build-basics/working-with-addresses">Working with Addresses</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("billing_address")]
    public Address? BillingAddress { get; init; }

    /// <summary>
    /// Represents a postal address in a country.
    /// For more information, see <see href="https://developer.squareup.com/docs/build-basics/working-with-addresses">Working with Addresses</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("shipping_address")]
    public Address? ShippingAddress { get; init; }

    /// <summary>
    /// An optional note to be entered by the developer when creating a payment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("note")]
    [MaxLength(500)]
    public string? Note { get; init; }

    /// <summary>
    /// Optional additional payment information to include on the customer's card statement
    /// as part of the statement description. This can be, for example, an invoice number, ticket number,
    /// or short description that uniquely identifies the purchase.
    /// <para>
    /// Note that the <c>statement_description_identifier</c> might get truncated on the statement description
    /// to fit the required information including the Square identifier (SQ *) and name of the
    /// seller taking the payment.
    /// </para>
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("statement_description_identifier")]
    [MaxLength(20)]
    public string? StatementDescriptionIdentifier { get; init; }

    /// <summary>
    /// Stores details about a cash payment. Contains only non-confidential information. For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments/cash-payments">Take Cash Payments</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cash_details")]
    public CashPaymentDetails? CashDetails { get; init; }

    /// <summary>
    /// Stores details about an external payment. Contains only non-confidential information.
    /// For more information, see
    /// <see href="https://developer.squareup.com/docs/payments-api/take-payments/external-payments">Take External Payments</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("external_details")]
    public ExternalPaymentDetails? ExternalDetails { get; init; }

    /// <summary>
    /// Details about the customer making the payment.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("customer_details")]
    public CustomerDetails? CustomerDetails { get; init; }

    /// <summary>
    /// Details specific to offline payments.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("offline_payment_details")]
    public OfflinePaymentDetails? OfflinePaymentDetails { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
